/* Shared code following mobyfunc; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x00242868 (was mobyfunc_00242868.c). */
#include "common.h"
#include "include_asm.h"

extern char *eudora_moby_class_headers[];
extern float IntToFloat(int);

/* Return the first frame of animation b of moby class a (0 when b is none). */
float animation_start(int a, unsigned int b)
{
    char *entry;
    char *nested;
    if (b >= 0xFF) return 0.0f;
    entry = eudora_moby_class_headers[a] + b * 4;
    nested = *(char **)(entry + 0x48);
    return IntToFloat(*(short *)(*(char **)(nested + 0x1C) + 4)) * 0.0625f;
}
/* Return the last frame of animation b of moby class a (0 when b is none). */
float animation_end(int a, unsigned int b)
{
    char *entry;
    char *nested;
    if (b >= 0xFF) return 0.0f;
    entry = eudora_moby_class_headers[a] + b * 4;
    nested = *(char **)(entry + 0x48);
    nested += ((unsigned char)nested[0x10] - 1) * 4;
    return IntToFloat(*(short *)(*(char **)(nested + 0x1C) + 4)) * 0.0625f;
}
